-- PREMIUM STUDIO HEADPHONES (8 products)
('audeze-lcd-5', 'Audeze LCD-5 Planar Magnetic Reference Headphones', 'audio', 2850000, 2790000, 2450000, 3, 0.42, '/assets/products/audeze-lcd-5.jpg', 'The absolute reference for critical listening. Audeze''s flagship LCD-5 utilizes ultra-thin Uniforce diaphragms and Fazor waveguides to deliver breathtaking resolution, transient speed, and a holographic soundstage that reveals every nuance in your music.', 1, unixepoch('2026-06-16'), 1, 2450000, '/assets/products/audeze-lcd-5.jpg', 2620000, 4.9, 1, 'Audeze', 1, 1),

('focal-utopia-2026', 'Focal Utopia 2026 Over-Ear Open-Back Audiophile Headphones', 'audio', 3200000, 3150000, 2750000, 2, 0.49, '/assets/products/focal-utopia-2026.jpg', 'French acoustic mastery redefined. The Utopia 2026 features beryllium dome drivers with a revised motor structure that eliminates all distortion, delivering a listening experience so transparent and dynamic it must be heard to be believed.', 1, unixepoch('2026-06-16'), 1, 2750000, '/assets/products/focal-utopia-2026.jpg', 2980000, 4.9, 0, 'Focal', 1, 1),

('sennheiser-hd-900', 'Sennheiser HD 900 Open-Back Audiophile Headphones', 'audio', 1250000, 1215000, 1050000, 5, 0.33, '/assets/products/sennheiser-hd900.jpg', 'The successor to the legendary HD 800 S. Handcrafted in Germany, the HD 900 features an all-new 56mm ring radiator transducer for an impossibly wide, natural soundstage with surgical precision across the entire frequency spectrum.', 1, unixepoch('2026-06-16'), 1, 1050000, '/assets/products/sennheiser-hd900.jpg', 1150000, 4.8, 1, 'Sennheiser', 1, 1),

('beyerdynamic-dt-1990-pro-mk2', 'Beyerdynamic DT 1990 Pro MK2 Tesla Studio Headphones', 'audio', 420000, 409000, 355000, 8, 0.37, '/assets/products/beyerdynamic-dt1990-mk2.jpg', 'The definitive tool for mixing and mastering engineers. Built in Germany, the MK2 features refined Tesla 2.0 drivers delivering exceptional detail retrieval and a brutally honest frequency response that reveals every flaw and every triumph in your mix.', 1, unixepoch('2026-06-16'), 1, 355000, '/assets/products/beyerdynamic-dt1990-mk2.jpg', 388000, 4.7, 1, 'Beyerdynamic', 1, 1),

('hifiman-arya-organic-2', 'HiFiMAN Arya Organic 2 Stealth Magnets Edition', 'audio', 750000, 729000, 635000, 6, 0.44, '/assets/products/hifiman-arya-organic-2.jpg', 'Hear every microscopic detail. The Arya Organic 2 combines HiFiMAN''s patented stealth magnet technology with a nanometer-thin diaphragm to achieve vanishingly low distortion and an expansive, immersive soundstage that rivals speakers costing ten times more.', 1, unixepoch('2026-06-16'), 1, 635000, '/assets/products/hifiman-arya-organic-2.jpg', 695000, 4.8, 1, 'HiFiMAN', 1, 1),

('meze-empyrean-3', 'Meze Audio Empyrean 3 Planar Magnetic Headphones - Copper', 'audio', 1850000, 1790000, 1580000, 4, 0.43, '/assets/products/meze-empyrean-3.jpg', 'Where Romanian craftsmanship meets acoustic perfection. The Empyrean 3 is a hand-assembled masterpiece featuring the new Isodynamic Hybrid Array 3 driver, delivering a lush, engaging sound signature with a comfort level that invites all-day listening sessions.', 1, unixepoch('2026-06-16'), 1, 1580000, '/assets/products/meze-empyrean-3.jpg', 1680000, 4.8, 0, 'Meze Audio', 1, 1),

('apple-airpods-studio-2', 'Apple AirPods Studio 2 Over-Ear ANC Headphones - Space Black', 'audio', 550000, 539000, 475000, 10, 0.29, '/assets/products/airpods-studio-2.jpg', 'Apple''s premium over-ear headphones reimagined. The H3 chip powers adaptive noise cancellation, personalized spatial audio with dynamic head tracking, and seamless device switching, all housed in a luxurious aluminum and knit mesh design.', 1, unixepoch('2026-06-16'), 1, 475000, '/assets/products/airpods-studio-2.jpg', 505000, 4.7, 1, 'Apple', 1, 1),

('dyson-zone-air-purifying', 'Dyson Zone Air-Purifying ANC Headphones - Prussian Blue', 'audio', 680000, 659000, 575000, 5, 0.67, '/assets/products/dyson-zone.jpg', 'Breathe cleaner air while you listen. The Dyson Zone combines premium active noise cancellation with a detachable, contact-free visor that captures 99% of pollutants, delivering filtered air directly to your nose and mouth in urban environments.', 1, unixepoch('2026-06-16'), 1, 575000, '/assets/products/dyson-zone.jpg', 625000, 4.3, 0, 'Dyson', 1, 1),

-- PREMIUM BOOKSHELF & HOME SPEAKERS (6 products)
('kef-lsx-ii-lt', 'KEF LSX II LT Wireless Hi-Fi Speakers Pair - Mineral White', 'audio', 850000, 829000, 720000, 4, 7.2, '/assets/products/kef-lsx-ii-lt.jpg', 'Audiophile-grade wireless sound in a compact form. KEF''s legendary Uni-Q driver array delivers pinpoint imaging from a point source, while HDMI ARC, USB-C, and AirPlay 2 make these the perfect marriage of hi-fi performance and modern convenience.', 1, unixepoch('2026-06-16'), 1, 720000, '/assets/products/kef-lsx-ii-lt.jpg', 780000, 4.8, 1, 'KEF', 1, 1),

('sonos-era-300-pair', 'Sonos Era 300 Pair Spatial Audio Smart Speakers - Matte Black', 'audio', 680000, 659000, 575000, 6, 8.7, '/assets/products/sonos-era-300-pair.jpg', 'Experience spatial audio as the artist intended. This pair of Era 300 speakers is engineered with six drivers each to disperse sound left, right, forward, and up, creating a breathtaking Dolby Atmos soundstage that fills every corner of your room.', 1, unixepoch('2026-06-16'), 1, 575000, '/assets/products/sonos-era-300-pair.jpg', 625000, 4.8, 1, 'Sonos', 1, 1),

('devialet-phantom-ii-108db', 'Devialet Phantom II 108dB Wireless Speaker - Iconic White', 'audio', 1350000, 1290000, 1150000, 3, 5.6, '/assets/products/devialet-phantom-ii.jpg', 'A physical shockwave from a compact sphere. The Phantom II delivers a staggering 108dB of ultra-dense sound with sub-bass extension down to 16Hz, thanks to Devialet''s patented ADH and HBI technologies that push the boundaries of acoustic physics.', 1, unixepoch('2026-06-16'), 1, 1150000, '/assets/products/devialet-phantom-ii.jpg', 1220000, 4.7, 0, 'Devialet', 1, 1),

('bowers-wilkins-zeppelin-mclaren', 'Bowers & Wilkins Zeppelin McLaren Edition Wireless Speaker', 'audio', 580000, 569000, 495000, 5, 6.5, '/assets/products/bw-zeppelin-mclaren.jpg', 'A collaboration of British engineering icons. The iconic Zeppelin silhouette is finished in McLaren''s signature Galvanic Grey, housing a 5-channel amplifier array and stereo DAC that fills any room with rich, detailed, room-filling sound.', 1, unixepoch('2026-06-16'), 1, 495000, '/assets/products/bw-zeppelin-mclaren.jpg', 535000, 4.7, 1, 'Bowers & Wilkins', 1, 1),

('jbl-authentics-500', 'JBL Authentics 500 Retro Smart Speaker with Dolby Atmos', 'audio', 480000, 469000, 410000, 8, 7.8, '/assets/products/jbl-authentics-500.jpg', 'Iconic Quadrex grille meets cutting-edge audio. The Authentics 500 combines a vintage-inspired design with modern Dolby Atmos spatial audio, simultaneous Alexa and Google Assistant, and room-filling 270W sound that honors JBL''s 75-year legacy.', 1, unixepoch('2026-06-16'), 1, 410000, '/assets/products/jbl-authentics-500.jpg', 438000, 4.6, 1, 'JBL', 1, 1),

('marshall-woburn-iii', 'Marshall Woburn III Bluetooth Speaker with HDMI - Black & Brass', 'audio', 420000, 409000, 355000, 7, 7.45, '/assets/products/marshall-woburn-iii.jpg', 'The loudest speaker in Marshall''s line-up delivers the massive, redefined sound that fills any space. With HDMI for your TV, Bluetooth 5.3 with LE Audio, and that unmistakable rock-and-roll aesthetic, it commands attention both sonically and visually.', 1, unixepoch('2026-06-16'), 1, 355000, '/assets/products/marshall-woburn-iii.jpg', 388000, 4.7, 1, 'Marshall', 1, 1),

-- NETWORKING EQUIPMENT (7 products)
('ubiquiti-dream-machine-se', 'Ubiquiti UniFi Dream Machine SE All-in-One Network Appliance', 'networking', 580000, 569000, 495000, 6, 4.5, '/assets/products/udm-se.jpg', 'Enterprise-grade networking for the discerning prosumer. The Dream Machine SE integrates a security gateway, 8-port PoE switch with 2.5GbE WAN, and an NVR slot for UniFi Protect cameras into a single, beautifully designed rack-mountable appliance.', 1, unixepoch('2026-06-16'), 1, 495000, '/assets/products/udm-se.jpg', 535000, 4.8, 1, 'Ubiquiti', 1, 1),

('ubiquiti-u7-pro-max', 'Ubiquiti UniFi U7 Pro Max WiFi 7 Access Point - Ceiling Mount', 'networking', 285000, 279000, 235000, 10, 0.65, '/assets/products/unifi-u7-pro-max.jpg', 'Blazing-fast WiFi 7 for the connected home or office. The U7 Pro Max delivers 10.8 Gbps aggregate throughput across the 2.4, 5, and 6 GHz bands, with dedicated spectral analysis and 300+ concurrent client support on the UniFi controller.', 1, unixepoch('2026-06-16'), 1, 235000, '/assets/products/unifi-u7-pro-max.jpg', 265000, 4.7, 1, 'Ubiquiti', 1, 1),

('tp-link-archer-be900', 'TP-Link Archer BE900 Quad-Band WiFi 7 Router with Touchscreen', 'networking', 350000, 339000, 288000, 8, 1.55, '/assets/products/tp-link-be900.jpg', 'A router that looks as futuristic as it performs. The BE900 features a vibrant touchscreen display, quad-band WiFi 7 with speeds up to 24.4 Gbps, dual 10G ports, and an array of 12 optimally positioned antennas for whole-home coverage.', 1, unixepoch('2026-06-16'), 1, 288000, '/assets/products/tp-link-be900.jpg', 318000, 4.6, 1, 'TP-Link', 1, 1),

('netgear-orbi-rbe973s', 'Netgear Orbi RBE973S Quad-Band WiFi 7 Mesh System (3-Pack)', 'networking', 1250000, 1215000, 1050000, 4, 4.2, '/assets/products/netgear-orbi-rbe973s.jpg', 'Eliminate dead zones forever. This 3-pack mesh system blankets up to 10,000 sq ft with quad-band WiFi 7, delivering multi-gigabit speeds to every corner. Dedicated backhaul ensures your mesh nodes communicate without impacting your devices'' performance.', 1, unixepoch('2026-06-16'), 1, 1050000, '/assets/products/netgear-orbi-rbe973s.jpg', 1150000, 4.7, 0, 'Netgear', 1, 1),

('mikrotik-rb5009ug-s-in', 'MikroTik RB5009UG+S+IN 10Gbps Router with PoE Out', 'networking', 185000, 179000, 148000, 10, 0.98, '/assets/products/mikrotik-rb5009.jpg', 'Uncompromising routing power in a compact form. The RB5009 features a powerful quad-core ARM CPU, a 10G SFP+ cage, a 2.5GbE port, and seven gigabit PoE-out ports, making it the ultimate tool for network engineers and homelab enthusiasts.', 1, unixepoch('2026-06-16'), 1, 148000, '/assets/products/mikrotik-rb5009.jpg', 168000, 4.7, 0, 'MikroTik', 1, 1),

('asus-rog-rapture-gt-be98', 'ASUS ROG Rapture GT-BE98 Quad-Band WiFi 7 Gaming Router', 'networking', 580000, 569000, 495000, 5, 2.1, '/assets/products/asus-gt-be98.jpg', 'Engineered for lag-free domination. With quad-band WiFi 7, triple-level game acceleration from device to server, a dedicated gaming port, and ROG-exclusive Aura RGB, this router ensures you see the enemy before they see you.', 1, unixepoch('2026-06-16'), 1, 495000, '/assets/products/asus-gt-be98.jpg', 535000, 4.7, 1, 'ASUS', 1, 1),

('gl-inet-flint-3', 'GL.iNet Flint 3 WiFi 7 Travel Router with VPN Client', 'networking', 85000, 82900, 68000, 15, 0.38, '/assets/products/gl-inet-flint-3.jpg', 'Secure, private internet from any hotel or coffee shop. This pocket-sized WiFi 7 travel router creates your own encrypted network with one-click WireGuard and OpenVPN client support, ensuring your data remains invisible on any public network.', 1, unixepoch('2026-06-16'), 1, 68000, '/assets/products/gl-inet-flint-3.jpg', 78000, 4.6, 1, 'GL.iNet', 1, 1),

