('keychron-q1-he', 'Keychron Q1 HE Wireless Hall-Effect Mechanical Keyboard ISO', 'accessories', 185000, 179000, 148000, 10, 1.65, '/assets/products/keychron-q1-he.jpg', 'The precision of magnetic switches meets premium build quality. The Q1 HE features Gateron double-rail hall-effect switches with adjustable actuation points, rapid trigger for competitive gaming, and a full CNC aluminum chassis for zero flex.', 1, unixepoch('2026-06-16'), 1, 148000, '/assets/products/keychron-q1-he.jpg', 168000, 4.7, 1, 'Keychron', 1, 1),

('wooting-80he-module', 'Wooting 80HE Analog Hall-Effect Gaming Keyboard - Black', 'accessories', 220000, 215000, 185000, 8, 1.18, '/assets/products/wooting-80he.jpg', 'The undisputed king of competitive gaming keyboards. Lekker V2 switches use magnetic analog sensing for 0.1mm precision on actuation and Rapid Trigger, while the open-source Wootility software gives you complete control over every key.', 1, unixepoch('2026-06-16'), 1, 185000, '/assets/products/wooting-80he.jpg', 205000, 4.8, 1, 'Wooting', 1, 1),

('corsair-k100-air-wireless', 'Corsair K100 AIR Wireless Ultra-Low Profile Mechanical Keyboard', 'accessories', 250000, 245000, 215000, 6, 0.78, '/assets/products/corsair-k100-air.jpg', 'Mechanical feel, laptop-thin profile. Corsair''s OPX Cherry MX Ultra-Low Profile switches deliver tactile mechanical feedback at just 11mm thick. Slipstream wireless, per-key RGB, and a brushed aluminum frame define premium.', 1, unixepoch('2026-06-16'), 1, 215000, '/assets/products/corsair-k100-air.jpg', 235000, 4.6, 0, 'Corsair', 1, 1),

('logitech-g915-x-lightspeed', 'Logitech G915 X LIGHTSPEED Full-Size Wireless RGB Mechanical Keyboard', 'accessories', 195000, 189000, 158000, 10, 1.05, '/assets/products/logitech-g915-x.jpg', 'The pinnacle of wireless mechanical gaming. The G915 X refines the iconic low-profile design with new POM switches, dual-shot PBT keycaps, 50-hour battery life, and Logitech''s lag-free LIGHTSPEED wireless technology.', 1, unixepoch('2026-06-16'), 1, 158000, '/assets/products/logitech-g915-x.jpg', 178000, 4.7, 1, 'Logitech', 1, 1),

('razer-blackwidow-v5-pro', 'Razer BlackWidow V5 Pro 75% Wireless Hot-Swappable Keyboard', 'accessories', 245000, 239000, 208000, 8, 0.92, '/assets/products/razer-blackwidow-v5.jpg', 'Razer''s first hot-swappable wireless keyboard. The compact 75% layout features Razer Gen-4 Orange tactile switches, HyperSpeed wireless with multi-device pairing, and an OLED command dial for quick macros and system monitoring.', 1, unixepoch('2026-06-16'), 1, 208000, '/assets/products/razer-blackwidow-v5.jpg', 225000, 4.6, 1, 'Razer', 1, 1),

('nuphy-air96-v3', 'NuPhy Air96 V3 Low-Profile Wireless Mechanical Keyboard', 'accessories', 125000, 119000, 98000, 12, 0.58, '/assets/products/nuphy-air96-v3.jpg', 'The ultimate travel keyboard for professionals. The Air96 V3 packs a full 96% layout into a remarkably thin aluminum frame, with new Cowberry switches, 2.4GHz, Bluetooth 5.3, and USB-C connectivity for seamless switching between your devices.', 1, unixepoch('2026-06-16'), 1, 98000, '/assets/products/nuphy-air96-v3.jpg', 112000, 4.6, 1, 'NuPhy', 1, 1),

('drop-ctrl-v3', 'Drop CTRL V3 TKL Hot-Swap Mechanical Keyboard Barebones', 'accessories', 165000, 159000, 132000, 6, 1.35, '/assets/products/drop-ctrl-v3.jpg', 'Build your endgame keyboard from the ground up. The CTRL V3 is a barebones TKL platform with a solid CNC aluminum case, per-key RGB, and 5-pin hot-swap sockets compatible with virtually every mechanical switch on the market.', 1, unixepoch('2026-06-16'), 1, 132000, '/assets/products/drop-ctrl-v3.jpg', 149000, 4.5, 0, 'Drop', 1, 1),

-- STREAMING & CONTENT CREATION (7 products)
('elgato-stream-deck-xl-2', 'Elgato Stream Deck XL 2 32-Key Studio Controller', 'accessories', 220000, 215000, 185000, 8, 0.85, '/assets/products/elgato-stream-deck-xl-2.jpg', 'Command your entire creative workflow from one panel. The 32 customizable LCD keys trigger macros, launch apps, control smart home devices, and manage your stream with a single press. The redesigned faceplate and dial add tactile precision.', 1, unixepoch('2026-06-16'), 1, 185000, '/assets/products/elgato-stream-deck-xl-2.jpg', 205000, 4.8, 1, 'Elgato', 1, 1),

('shure-sm7db', 'Shure SM7dB Active Dynamic Broadcast Microphone with Built-In Preamp', 'audio', 380000, 369000, 315000, 6, 0.77, '/assets/products/shure-sm7db.jpg', 'The broadcast legend, now with a built-in preamp. The SM7dB delivers the iconic warm, smooth vocal tone trusted by podcasters and streamers worldwide, while the onboard Shure-designed preamp eliminates the need for an external signal booster.', 1, unixepoch('2026-06-16'), 1, 315000, '/assets/products/shure-sm7db.jpg', 348000, 4.8, 1, 'Shure', 1, 1),

('rode-rcaster-duo-2', 'RØDE RØDECaster Duo 2 Compact Podcast Production Studio', 'audio', 480000, 469000, 410000, 5, 1.25, '/assets/products/rodecaster-duo-2.jpg', 'A complete broadcast studio that fits on your desk. Two high-gain Revolution Preamps, tactile faders, customizable SMART pads, and built-in effects processing make professional podcasting, streaming, and content creation effortless.', 1, unixepoch('2026-06-16'), 1, 410000, '/assets/products/rodecaster-duo-2.jpg', 438000, 4.8, 1, 'RØDE', 1, 1),

('elgato-facecam-mk3', 'Elgato Facecam Mk.3 4K60 Webcam with Sony STARVIS 2 Sensor', 'accessories', 185000, 179000, 148000, 12, 0.18, '/assets/products/elgato-facecam-mk3.jpg', 'True 4K at a buttery 60fps. The Facecam Mk.3 leverages a large Sony STARVIS 2 sensor for exceptional low-light performance, uncompressed video, and cinematic manual controls via Camera Hub software, making it the webcam of choice for serious creators.', 1, unixepoch('2026-06-16'), 1, 148000, '/assets/products/elgato-facecam-mk3.jpg', 168000, 4.7, 1, 'Elgato', 1, 1),

('godox-sl300iii', 'Godox SL300III 330W Daylight LED Video Light with Bowens Mount', 'accessories', 285000, 279000, 235000, 4, 3.2, '/assets/products/godox-sl300iii.jpg', 'Studio-grade illumination that commands professional results. The SL300III outputs a powerful, flicker-free 330W of 5600K daylight-balanced light with silent fan cooling, Bowens mount compatibility, and 0-100% dimming for precise control.', 1, unixepoch('2026-06-16'), 1, 235000, '/assets/products/godox-sl300iii.jpg', 265000, 4.6, 0, 'Godox', 1, 1),

('elgato-wave-xlr-mk2', 'Elgato Wave XLR Mk.2 USB Condenser Microphone Interface', 'accessories', 125000, 119000, 98000, 15, 0.38, '/assets/products/elgato-wave-xlr-mk2.jpg', 'Transform any XLR microphone into a broadcast powerhouse. The Wave XLR Mk.2 provides up to 75dB of ultra-clean gain, Clipguard anti-distortion, a capacitive mute button, and Wave Link integration for professional audio routing in seconds.', 1, unixepoch('2026-06-16'), 1, 98000, '/assets/products/elgato-wave-xlr-mk2.jpg', 112000, 4.7, 1, 'Elgato', 1, 1),

('nanlite-pavotube-ii-30x', 'Nanlite PavoTube II 30X 4ft RGBWW LED Pixel Tube Light Kit', 'accessories', 250000, 245000, 215000, 5, 2.5, '/assets/products/nanlite-pavotube-ii.jpg', 'Paint your scene with limitless color. This 4-foot pixel tube light features individually addressable LEDs for matrix effects, a full RGBWW spectrum, and a built-in battery for location shoots, turning any space into a cinematic environment.', 1, unixepoch('2026-06-16'), 1, 215000, '/assets/products/nanlite-pavotube-ii.jpg', 235000, 4.6, 0, 'Nanlite', 1, 1),

-- PREMIUM LAPTOP & DESK ACCESSORIES (8 products)
('caldigit-ts5-plus', 'CalDigit TS5 Plus Thunderbolt 5 Dock - 24-Port', 'accessories', 450000, 439000, 380000, 5, 1.52, '/assets/products/caldigit-ts5-plus.jpg', 'The undisputed king of Thunderbolt docks. The TS5 Plus leverages Thunderbolt 5''s 120Gbps bandwidth to drive dual 8K displays, connect 24 peripherals, and deliver 240W host charging through a single cable—the ultimate desktop command center.', 1, unixepoch('2026-06-16'), 1, 380000, '/assets/products/caldigit-ts5-plus.jpg', 415000, 4.9, 1, 'CalDigit', 1, 1),

('owc-thunderbolt-5-hub', 'OWC Thunderbolt 5 Hub 4-Port with 140W PD', 'accessories', 185000, 179000, 148000, 8, 0.42, '/assets/products/owc-tb5-hub.jpg', 'Multiply your Thunderbolt 5 potential. Three downstream TB5 ports and one USB-A port branch from a single connection, each capable of 80Gbps bidirectional throughput and daisy-chaining to 5 additional Thunderbolt devices.', 1, unixepoch('2026-06-16'), 1, 148000, '/assets/products/owc-tb5-hub.jpg', 168000, 4.7, 0, 'OWC', 1, 1),

('satechi-dual-dock-stand', 'Satechi Dual Dock Stand for MacBook & iPad Pro - Space Grey', 'accessories', 125000, 119000, 98000, 10, 1.25, '/assets/products/satechi-dual-dock.jpg', 'A single elegant stand for your entire Apple ecosystem. Machined from a solid block of aluminum, it holds your MacBook vertically while your iPad Pro mounts beside it, with an integrated USB-C hub connecting both to your desktop peripherals.', 1, unixepoch('2026-06-16'), 1, 98000, '/assets/products/satechi-dual-dock.jpg', 112000, 4.6, 1, 'Satechi', 1, 1),

('benq-screenbar-halo-2', 'BenQ ScreenBar Halo 2 Smart Monitor Light with Wireless Controller', 'accessories', 125000, 119000, 98000, 15, 0.55, '/assets/products/benq-screenbar-halo-2.jpg', 'Illuminate your workspace, not your screen. The patented asymmetrical optical design bathes your desk in adjustable, eye-care-certified light with zero screen glare. The new wireless controller and rear ambient light transform your desktop ambiance.', 1, unixepoch('2026-06-16'), 1, 98000, '/assets/products/benq-screenbar-halo-2.jpg', 112000, 4.8, 1, 'BenQ', 1, 1),

('gro-made-wood-magsafe-stand', 'Grovemade Walnut Wood MagSafe Charging Stand for iPhone', 'accessories', 85000, 82900, 68000, 12, 0.72, '/assets/products/grovemade-magsafe-stand.jpg', 'Natural materials elevate your tech. Handcrafted from American black walnut with a vegetable-tanned leather base, this stand integrates an Apple-certified 25W MagSafe puck in a design that transforms your desk into a warm, sophisticated workspace.', 1, unixepoch('2026-06-16'), 1, 68000, '/assets/products/grovemade-magsafe-stand.jpg', 78000, 4.7, 0, 'Grovemade', 1, 1),

('herman-miller-ollin-monitor-arm', 'Herman Miller Ollin Monitor Arm - Studio White', 'accessories', 320000, 315000, 275000, 5, 3.8, '/assets/products/herman-miller-ollin.jpg', 'Engineering meets elegance for your display. Co-designed by Herman Miller and Colebrook Bosson Saunders, the Ollin arm floats your monitor with frictionless, fluid movement in every direction, with integrated cable management that disappears into the sculptural form.', 1, unixepoch('2026-06-16'), 1, 275000, '/assets/products/herman-miller-ollin.jpg', 298000, 4.8, 0, 'Herman Miller', 1, 1),

('jabra-speak2-75', 'Jabra Speak2 75 Professional Wireless Speakerphone for Meetings', 'audio', 250000, 245000, 215000, 10, 0.47, '/assets/products/jabra-speak2-75.jpg', 'Command every hybrid meeting with crystal clarity. The Speak2 75 features a full-duplex, four-microphone array that captures voices from 360 degrees, advanced noise suppression, and certified compatibility with Microsoft Teams, Zoom, and Google Meet.', 1, unixepoch('2026-06-16'), 1, 215000, '/assets/products/jabra-speak2-75.jpg', 235000, 4.7, 1, 'Jabra', 1, 1),

('logitech-sight-tabletop-camera', 'Logitech Sight AI-Powered Tabletop Multi-Camera System', 'accessories', 380000, 369000, 315000, 4, 1.2, '/assets/products/logitech-sight.jpg', 'Give remote participants a seat at the table. Sight uses dual 4K cameras and AI to intelligently frame and switch between in-person speakers in medium-to-large meeting rooms, integrating seamlessly with Rally Bar systems for a complete hybrid meeting solution.', 1, unixepoch('2026-06-16'), 1, 315000, '/assets/products/logitech-sight.jpg', 348000, 4.7, 0, 'Logitech', 1, 1),

